C460_R = [('    if (CHAPTER) { z.hp = z.maxHp; if (z.hpBar) z.hpDisp = z.hp; }   // c432: 지정되는 순간 체력 가득', '    if (CHAPTER) { z.hp = z.maxHp; if (z.hpBar) z.hpDisp = z.hp; z.force = (z.force || 1) * 3; }   // c460: 미는 힘 3배 · c432: 지정되는 순간 체력 가득'), ("    if (z.mut === 'armor') { n += 2; const B = chMB(z); if (B && B.id === 'monster') n += B.r; }", "    if (z.mut === 'armor') { n += 2; const B = chMB(z); if (B && B.id === 'monster') n += B.r; }\n    if (z.bombing) n += 2;   // c460: 자폭하러 가는 동료 = 방탄복 2개"), ("function chArmF(z) { const B = chMB(z); return 7 + (B && B.id === 'monster' ? 7 * B.r / 6 : 0); }", "function chArmF(z) { const B = chMB(z); return (7 + (B && B.id === 'monster' ? 7 * B.r / 6 : 0)) * (z.bombing ? 3 : 1); }   /* c460: 자폭 중 3배 */")]
